/**
 * Start downloading the chunks main() will import later, without running them.
 *
 * main() imports the pixel chunks only after the consent module has loaded
 * and pmw.consent.load() has resolved, which waits up to two seconds for an
 * asynchronous CMP. Until then no pixel chunk was even requested, so the
 * downloads queued up behind the consent step. Fetching them here, as soon
 * as the public path is known, overlaps both.
 *
 * __webpack_chunk_load__() installs a chunk's module factories without
 * executing any module. The import() in main() then finds the chunk in place
 * and runs the loader at exactly the point it always did, after consent and
 * the command queue. Running the loaders early instead would register
 * listeners before queued snippets had their turn.
 *
 * The URL is built by webpack's own runtime from the same public path the
 * later import() uses, so there is never a second download of a chunk. That
 * is why this lives here and not in PHP as <link rel="preload">: a CDN
 * rewrite of the link but not of chunk_base_path, a cached page naming
 * chunks from an earlier release, or a delay-JS plugin holding back the main
 * bundle would each turn a preload hint into a wasted or duplicate download.
 *
 * A chunk that fails to download here is retried by the import() later,
 * which reports the error as before.
 *
 * Requires optimization.chunkIds "named" (gulp-webpack.js), so a chunk's id
 * is its webpackChunkName. A chunk's own async dependencies are not fetched
 * here; ip-geo, with its vendors chunk, is the only chunk that has any and it
 * is not prefetched.
 *
 * @since 1.70.1
 */

/** Pixel key in pmwDataLayer.pixels -> webpackChunkName in main.js, free and Pro builds. */
const PIXEL_CHUNKS = {
	google   : "pixel-google",
	facebook : "pixel-facebook",
	hotjar   : "pixel-hotjar",
	bing     : "pixel-microsoft",
	openai   : "pixel-openai",
	pinterest: "pixel-pinterest",
	reddit   : "pixel-reddit",
	snapchat : "pixel-snapchat",
	tiktok   : "pixel-tiktok",
}

