/**
 * Names of the chunks main() is going to import on this page.
 *
 * Mirrors the conditions in main(): nothing for an excluded domain or for a
 * visitor already known to be excluded, only enabled pixels, Pro chunks only
 * when Pro features can load.
 *
 * @param {object} pmw
 * @param {object} dataLayer pmwDataLayer
 * @returns {string[]}
 */
const getChunksToPrefetch = (pmw, dataLayer) => {

	if (pmw.excludeDomainFromTracking()) return []

	const chunks = ["doofinder-listener"]

	if (window.wp?.hooks) chunks.push("wc-hooks")

	if (dataLayer?.general?.modules?.load_deprecated_functions !== false) chunks.push("deprecated-functions")

	// isVisitorAllowedSync() is idempotent; main() calls it again later.
	// null means the async IP lookup decides, and main() loads the pixels.
	if (pmw.isVisitorAllowedSync() === false) return chunks

	const pixels = dataLayer?.pixels || {}

	Object.entries(PIXEL_CHUNKS).forEach(([key, chunk]) => {
		if (pixels[key]) chunks.push(chunk)
	})

	// #if process.env.TIER === 'premium'
// 	if (pmw.canLoadPremiumFeatures()) {
// 
// 		chunks.push("pmw-premium-events")
// 
// 		Object.entries(PREMIUM_PIXEL_CHUNKS).forEach(([key, chunk]) => {
// 			if (pixels[key]) chunks.push(chunk)
// 		})
// 	}
	// #endif

	return chunks
}

/**
 * Start the downloads. Never throws and never rejects.
 *
 * @param {object} pmw
 * @param {object} dataLayer pmwDataLayer
 */
const prefetchChunks = (pmw, dataLayer) => {

	// Only the webpack build has a chunk loader (not the unit test harness)
	// eslint-disable-next-line camelcase, no-undef
	if (typeof __webpack_chunk_load__ !== "function") return

	try {
		getChunksToPrefetch(pmw, dataLayer).forEach(chunk => {
			// eslint-disable-next-line camelcase, no-undef
			__webpack_chunk_load__(chunk).catch(() => {})
		})
	} catch (error) {
		pmw.console.error("Chunk prefetch failed:", error)
	}
}

module.exports = {
	PIXEL_CHUNKS,
	// #if process.env.TIER === 'premium'
// 	PREMIUM_PIXEL_CHUNKS,
	// #endif
	getChunksToPrefetch,
	prefetchChunks,
}
